def simulate_disease_spread(population_size, initial_infected, days, transmission_rate):
    import random

    # Initialize population
    population = ['S'] * (population_size - initial_infected) + ['I'] * initial_infected
    random.shuffle(population)

    # Simulation loop
    results = []
    for day in range(days):
        infected_count = population.count('I')
        susceptible_count = population_size - infected_count

        # Record current state
        results.append({
            'day': day,
            'susceptible': susceptible_count,
            'infected': infected_count
        })

        # Transmission process
        new_population = []
        for person in population:
            if person == 'S':
                # Susceptible person can get infected
                if any(random.random() < transmission_rate for _ in [p for p in population if p == 'I']):
                    new_population.append('I')
                else:
                    new_population.append('S')
            else:
                # Infected person remains infected
                new_population.append('I')

        population = new_population

    return results

